ejemplo.codigo:
class AsientoOcupado(Exception):
    pass

def reservar(ocupados, asiento):
    if asiento in ocupados:
        raise AsientoOcupado(asiento)
    return sorted(ocupados + [asiento])

def intentar_reserva(ocupados, asiento):
    try:
        return reservar(ocupados, asiento)
    except AsientoOcupado:
        return ocupados

intentar_reserva(["A1", "B2"], "A1")  # ['A1', 'B2']

